-- 219: Original BrillaPrep WASSCE BrillaPrep transitional Sculpture beta content blueprint questions, part 7.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_219_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_219_guard;
INSERT INTO _migration_219_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_025' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_5' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How should plaster normally be introduced when preparing a controlled casting mix?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Add dry powder after the plaster begins to thicken to restore fluidity","B. Sift plaster gradually into measured clean water, allow it to wet, then mix gently","C. Mix the plaster with dirty tool-washing water to slow its setting time","D. Pour water into an unmeasured heap of plaster and beat it immediately"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Measured water and gradual sifting give repeatable consistency and full wetting. Gentle mixing limits entrained air, and the batch must be placed within its natural working time. Therefore the correct answer is B: Sift plaster gradually into measured clean water, allow it to wet, then mix gently.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_5' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_025' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_219_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_026' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_6' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What should guide the choice of a joint between two different assemblage materials?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A rigid adhesive is suitable whenever both surfaces feel smooth","B. The joint should be visually hidden even if it cannot transfer the load","C. The strongest fastener is always best regardless of the weaker material","D. Expected loads, surface condition, material compatibility and dimensional movement"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Connection design follows the load path and both materials. Fasteners, welds or adhesives must suit the surfaces, environment and expected movement without damaging the components. Therefore the correct answer is D: Expected loads, surface condition, material compatibility and dimensional movement.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_6' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_026' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_219_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_027' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_6' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why does triangulation stiffen a lightweight constructed sculpture?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A triangle resists shape change unless a member or joint deforms","B. A triangular frame shares every force equally, so member size and joint stiffness no longer affect stability","C. One diagonal brace on the front plane automatically prevents racking and twisting on every plane of a three-dimensional frame","D. The added diagonal increases dead weight, which presses the corner joints firmly enough to stop racking"]' AND q.correct_answer IS 'A' AND q.explanation IS 'A diagonal converts a flexible frame into linked triangles. Their members carry axial forces instead of allowing corners to shear freely, provided the joints and sections are adequate. Therefore the correct answer is A: A triangle resists shape change unless a member or joint deforms.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_6' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_027' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_219_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_028' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_6' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why must an upright assemblage be secured to an adequately sized base?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The footprint and connection must resist overturning from weight distribution and external forces","B. A heavier top automatically lowers the combined centre of gravity","C. Surface adhesive alone can replace a designed mechanical load path","D. A visually symmetrical upper form makes the base size irrelevant"]' AND q.correct_answer IS 'A' AND q.explanation IS 'A stable sculpture keeps its combined centre of gravity within its support area and transfers overturning forces through a capable connection. Public display also requires foreseeable contact to be considered. Therefore the correct answer is A: The footprint and connection must resist overturning from weight distribution and external forces.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_6' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_028' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_025', 'topic_was_sculpture_b004_5', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'How should plaster normally be introduced when preparing a controlled casting mix?', 'multiple_choice', NULL, '["A. Add dry powder after the plaster begins to thicken to restore fluidity","B. Sift plaster gradually into measured clean water, allow it to wet, then mix gently","C. Mix the plaster with dirty tool-washing water to slow its setting time","D. Pour water into an unmeasured heap of plaster and beat it immediately"]', 'B', 'Measured water and gradual sifting give repeatable consistency and full wetting. Gentle mixing limits entrained air, and the batch must be placed within its natural working time. Therefore the correct answer is B: Sift plaster gradually into measured clean water, allow it to wet, then mix gently.', 'easy', '3', '3', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_5', 'Explain', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_026', 'topic_was_sculpture_b004_6', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'What should guide the choice of a joint between two different assemblage materials?', 'multiple_choice', NULL, '["A. A rigid adhesive is suitable whenever both surfaces feel smooth","B. The joint should be visually hidden even if it cannot transfer the load","C. The strongest fastener is always best regardless of the weaker material","D. Expected loads, surface condition, material compatibility and dimensional movement"]', 'D', 'Connection design follows the load path and both materials. Fasteners, welds or adhesives must suit the surfaces, environment and expected movement without damaging the components. Therefore the correct answer is D: Expected loads, surface condition, material compatibility and dimensional movement.', 'medium', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_6', 'Identify', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_027', 'topic_was_sculpture_b004_6', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'Why does triangulation stiffen a lightweight constructed sculpture?', 'multiple_choice', NULL, '["A. A triangle resists shape change unless a member or joint deforms","B. A triangular frame shares every force equally, so member size and joint stiffness no longer affect stability","C. One diagonal brace on the front plane automatically prevents racking and twisting on every plane of a three-dimensional frame","D. The added diagonal increases dead weight, which presses the corner joints firmly enough to stop racking"]', 'A', 'A diagonal converts a flexible frame into linked triangles. Their members carry axial forces instead of allowing corners to shear freely, provided the joints and sections are adequate. Therefore the correct answer is A: A triangle resists shape change unless a member or joint deforms.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_6', 'Explain', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_028', 'topic_was_sculpture_b004_6', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'Why must an upright assemblage be secured to an adequately sized base?', 'multiple_choice', NULL, '["A. The footprint and connection must resist overturning from weight distribution and external forces","B. A heavier top automatically lowers the combined centre of gravity","C. Surface adhesive alone can replace a designed mechanical load path","D. A visually symmetrical upper form makes the base size irrelevant"]', 'A', 'A stable sculpture keeps its combined centre of gravity within its support area and transfers overturning forces through a capable connection. Public display also requires foreseeable contact to be considered. Therefore the correct answer is A: The footprint and connection must resist overturning from weight distribution and external forces.', 'easy', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_6', 'Explain', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-visual-arts-beta-004', 'automated_beta', 'beta', 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.', 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf', 0, 1 FROM questions WHERE id IN ('q_was_sculpture_b004_025', 'q_was_sculpture_b004_026', 'q_was_sculpture_b004_027', 'q_was_sculpture_b004_028');
